import path from "node:path";
import { build } from "vite";
import { toPosix } from "./groups.mjs";

const virtualEntryId = "\0crestapps-assets-entry";
const scriptExtensions = new Set([".js", ".mjs", ".ts"]);
const styleExtensions = new Set([".css", ".scss"]);

const banner =
    "/*\n" +
    "** NOTE: This file is generated by the assets build (npm run build) and should not be edited directly!\n" +
    "** Edit its sources under Assets/ and rebuild; see Assets.json for the files it is built from.\n" +
    "*/\n";

// Builds a 'vite' asset group into its readable output (dest) and its minified sibling (*.min.js or *.min.css).
// Returns the files to write and every source file that went into them, which the build cache hashes to decide
// whether the group needs building next time.
export async function buildViteGroup(group) {
    const kind = getGroupKind(group);
    const [readable, minified] = await Promise.all([
        bundle(group, kind, false),
        bundle(group, kind, true),
    ]);

    return {
        files: [
            { path: group.destPath, contents: readable.contents },
            { path: toMinifiedPath(group.destPath), contents: minified.contents },
        ],
        inputs: [...new Set([...readable.inputs, ...minified.inputs])].sort(),
    };
}

export function getViteOutputs(group) {
    return [group.destPath, toMinifiedPath(group.destPath)];
}

function getGroupKind(group) {
    const destExtension = path.extname(group.destPath).toLowerCase();
    const allowed = destExtension === ".js" ? scriptExtensions : destExtension === ".css" ? styleExtensions : null;

    if (allowed === null) {
        throw new Error(`${group.relativeManifestPath} (${group.name}): a 'vite' group's 'dest' must be a .js or .css file.`);
    }

    for (const source of group.sourcePaths) {
        if (!allowed.has(path.extname(source).toLowerCase())) {
            throw new Error(`${group.relativeManifestPath} (${group.name}): '${source}' cannot be built into a ${destExtension} file.`);
        }
    }

    if (group.global !== undefined && (destExtension !== ".js" || group.sourcePaths.length !== 1)) {
        throw new Error(`${group.relativeManifestPath} (${group.name}): 'global' needs exactly one script source.`);
    }

    return destExtension === ".js" ? "script" : "style";
}

async function bundle(group, kind, minify) {
    const result = await build({
        configFile: false,
        envDir: false,
        root: group.basePath,
        publicDir: false,
        logLevel: "warn",
        clearScreen: false,
        css: {
            // An inline (empty) config stops Vite from searching the folders above for a PostCSS config.
            postcss: {},
        },
        plugins: [entryPlugin(group)],
        build: {
            write: false,
            emptyOutDir: false,
            copyPublicDir: false,
            reportCompressedSize: false,
            modulePreload: false,
            sourcemap: false,
            minify: minify ? "oxc" : false,
            cssMinify: minify ? "lightningcss" : false,
            cssCodeSplit: false,
            rolldownOptions: {
                input: virtualEntryId,
                // The sources are browser scripts that attach themselves to globals. Keep every statement, in order, the
                // way the concatenating pipeline did; vendor bundles exposed through 'global' are tree-shaken.
                treeshake: group.global !== undefined,
                // Vite drops an app entry's exports by default; the exports are what a 'global' group exposes.
                preserveEntrySignatures: group.global !== undefined ? "strict" : false,
                output: {
                    format: "iife",
                    name: group.global,
                    banner: minify || kind === "style" ? undefined : banner,
                    entryFileNames: "[name].js",
                    assetFileNames: "[name][extname]",
                },
            },
        },
    });

    const output = (Array.isArray(result) ? result : [result]).flatMap(entry => entry.output);
    const inputs = output
        .filter(item => item.type === "chunk")
        .flatMap(chunk => chunk.moduleIds)
        .filter(id => !id.startsWith("\0") && path.isAbsolute(id))
        .map(id => toPosix(id.split("?")[0]));

    if (kind === "style") {
        const css = output.filter(item => item.type === "asset" && item.fileName.endsWith(".css"));

        if (css.length !== 1) {
            throw new Error(`${group.relativeManifestPath} (${group.name}): expected one stylesheet from the build, got ${css.length}.`);
        }

        return { contents: toLf(asString(css[0].source)), inputs: [...inputs, ...group.sourcePaths] };
    }

    const chunk = output.find(item => item.type === "chunk" && item.isEntry);

    return { contents: toLf(chunk.code), inputs };
}

// The entry imports each source in the order Assets.json lists them, so the bundle runs them in that order, exactly as
// the concatenated file did. A group with a 'global' re-exports its one source and exposes it as window[global].
function entryPlugin(group) {
    return {
        name: "crestapps-assets-entry",
        resolveId(id) {
            return id === virtualEntryId ? virtualEntryId : null;
        },
        load(id) {
            if (id !== virtualEntryId) {
                return null;
            }

            // The namespace, rather than `export *`, so a CommonJS package (whose names are only known at run time)
            // is exposed whole, the same as an ES module.
            if (group.global !== undefined) {
                return `import * as namespace from ${JSON.stringify(group.sourcePaths[0])};\nexport default namespace;\n`;
            }

            return group.sourcePaths.map(source => `import ${JSON.stringify(source)};\n`).join("");
        },
    };
}

function toMinifiedPath(destPath) {
    const extension = path.extname(destPath);

    return `${destPath.substring(0, destPath.length - extension.length)}.min${extension}`;
}

function asString(source) {
    return typeof source === "string" ? source : Buffer.from(source).toString("utf8");
}

function toLf(text) {
    const normalized = text.replace(/\r\n/g, "\n");

    return normalized.endsWith("\n") ? normalized : `${normalized}\n`;
}
